<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">var</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> headerRe </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> regexp.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MustCompile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">\`&lt;​div class=&quot;news_li&quot;[\\s\\S]*?&lt;​h2&gt;[\\s\\S]*?&lt;​a.*?t</span></span>
